let giftMap=['5655','5269','6064',''],socket,serverRevision=0,applyingRemote=false,admin=false,ready=false,syncTimer,retryTimer;
const panel=document.createElement('section');panel.className='live-connection';panel.innerHTML=`<div class="panel-title"><strong>پنل مدیریت لدو لایو</strong><button id="hidePanel">بستن پنل و نمایش لایو</button></div><p id="liveStatus" role="status">در حال دریافت وضعیت…</p><div id="authBox" class="map-row"><input id="adminKey" type="password" placeholder="کلید مدیریت" aria-label="کلید مدیریت"><button id="unlock">ورود به پنل</button></div><div id="adminTools" hidden><div class="map-row"><input id="liveUsername" placeholder="نام حساب تیک‌تاک بدون @" aria-label="نام حساب تیک‌تاک"><button id="connectLive">اتصال به لایو</button><button id="disconnectLive">قطع و حالت آزمایشی</button></div><div id="giftMappings"></div><p id="lastLiveGift" class="muted"></p><div class="map-row"><button id="demo0">آزمایش گوشه ۱</button><button id="demo1">آزمایش گوشه ۲</button><button id="demo2">آزمایش گوشه ۳</button><button id="demo3">آزمایش گوشه ۴</button></div><p class="muted">گیفت هر گوشه را با شناسهٔ یکتا تنظیم کنید. آخرین فرستنده خودکار در قاب همان کشور نمایش داده می‌شود.</p></div>`;
document.querySelector('main').prepend(panel);const toggle=document.createElement('button');toggle.className='panel-toggle';toggle.textContent='⚙ پنل مدیریت';toggle.onclick=()=>{document.body.classList.remove('broadcast');panel.scrollIntoView({behavior:'smooth'})};document.body.append(toggle);
const originalRender=render;render=function(){originalRender();drawProfiles()};
function drawProfiles(){document.querySelectorAll('.player-frame').forEach(e=>e.remove());const positions=['top-left','top-right','bottom-right','bottom-left'];state.teams.forEach((t,i)=>{const h=document.querySelectorAll('.home')[i];if(h)h.style.setProperty('--home-color',['#e4bd12','#1ea8ee','#e62f44','#08a24c'][i]);const frame=document.createElement('div');frame.className='player-frame '+positions[i];frame.id='player-frame-'+i;const face=document.createElement('div');face.className='profile-face';face.textContent='👤';if(t.supporter?.avatar){const img=document.createElement('img');img.src=t.supporter.avatar;img.alt=t.supporter.name;img.referrerPolicy='no-referrer';img.onerror=()=>img.remove();face.append(img)}const country=document.createElement('div');country.className='player-country';country.textContent=t.flag+' '+t.name;const name=document.createElement('div');name.className='player-name';name.textContent=t.supporter?.name||'منتظر حامی';const gift=document.createElement('div');gift.className='player-gift';gift.textContent=(t.supporter?.giftName||t.gift)+' · '+t.g;frame.append(face,country,name,gift);document.querySelector('.board-wrap').append(frame)});$('giftMappings').replaceChildren();state.teams.forEach((t,i)=>{const row=document.createElement('label');row.className='map-row';const label=document.createElement('span');label.textContent=t.flag+' '+t.name+' · '+t.gift;const input=document.createElement('input');input.placeholder='شناسهٔ گیفت';input.setAttribute('aria-label','شناسه گیفت '+t.name);input.inputMode='numeric';input.value=giftMap[i]||'';input.onchange=()=>{const value=input.value.trim();if(value&&(!/^\d+$/.test(value)||giftMap.some((v,j)=>j!==i&&v===value))){message('شناسه باید عددی و برای هر کشور یکتا باشد.');input.value=giftMap[i]||'';return}giftMap[i]=value;localStorage.setItem('ludo-gift-map',JSON.stringify(giftMap));queueSync()};row.append(label,input);$('giftMappings').append(row)})}

const originalPersist=persist;persist=function(){originalPersist();queueSync()};
function collect(){return{state,config,giftMap,likes:likeCount,fans,display:{portrait:document.body.classList.contains('portrait'),bg:localStorage.getItem('ludo-bg')||'#113a72',width:localStorage.getItem('ludo-width')||100,volume:Number($('volume').value),effects:$('effects').checked,sound:$('sound').checked}}}
function queueSync(){if(applyingRemote||!admin||!ready)return;clearTimeout(syncTimer);syncTimer=setTimeout(()=>{if(socket?.readyState===1)socket.send(JSON.stringify({type:'update',revision:serverRevision,snapshot:collect()}))},100)}
function remote(m){applyingRemote=true;serverRevision=m.revision;const s=m.snapshot;state=s.state;config=s.config;giftMap=s.giftMap;likeCount=s.likes||0;fans=s.fans||[];render();fanRender();$('likes').textContent=likeCount;const d=s.display||{};$('effects').checked=d.effects!==false;$('sound').checked=!!d.sound;$('volume').value=d.volume??20;document.body.classList.toggle('portrait',d.portrait!==false);if(d.bg){document.body.style.background=d.bg;localStorage.setItem('ludo-bg',d.bg)}document.querySelector('main').style.maxWidth=(Number(d.width||100)*14.4)+'px';$('liveStatus').textContent=m.status;$('liveUsername').placeholder=m.username?'@'+m.username:'نام حساب تیک‌تاک بدون @';ready=true;applyingRemote=false}
function command(type,rest={}){if(socket?.readyState===1)socket.send(JSON.stringify({type,...rest}));else message('ارتباط با سرور قطع است.')}
function authenticate(){const key=$('adminKey').value.trim()||sessionStorage.getItem('ludo-admin')||decodeURIComponent(location.hash.slice(1));if(key)command('auth',{token:key})}
function openSocket(){clearTimeout(retryTimer);socket=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/events');socket.onopen=authenticate;socket.onmessage=event=>{try{const m=JSON.parse(event.data);if(m.type==='snapshot')remote(m);else if(m.type==='auth'){admin=m.ok;document.body.classList.toggle('can-manage',admin);$('authBox').hidden=admin;$('adminTools').hidden=!admin;if(admin){const key=$('adminKey').value.trim()||sessionStorage.getItem('ludo-admin')||decodeURIComponent(location.hash.slice(1));sessionStorage.setItem('ludo-admin',key);$('adminKey').value='';message('پنل مدیریت آماده است.')}else message('کلید مدیریت معتبر نیست.')}else if(m.type==='effect'){effect(m.symbol);if(Number.isInteger(m.corner))$('player-frame-'+m.corner)?.classList.add('new-gift')}else if(m.type==='last-gift')$('lastLiveGift').textContent='آخرین گیفت: '+m.giftName+' · ID '+m.giftId;else if(m.type==='error')message(m.message)}catch{}};socket.onclose=()=>{admin=false;document.body.classList.remove('can-manage');$('liveStatus').textContent='ارتباط سرور قطع شد؛ تلاش مجدد…';retryTimer=setTimeout(openSocket,3000)}}
$('unlock').onclick=authenticate;$('hidePanel').onclick=()=>document.body.classList.add('broadcast');$('connectLive').onclick=()=>command('connect',{username:$('liveUsername').value.trim()});$('disconnectLive').onclick=()=>command('disconnect');for(let i=0;i<4;i++)$('demo'+i).onclick=()=>command('demo-gift',{corner:i});document.addEventListener('change',queueSync);document.addEventListener('click',()=>{if(admin)setTimeout(queueSync,0)});drawProfiles();openSocket();if(location.pathname==='/screen')document.body.classList.add('broadcast');
